#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/controls/docking/dock_workspace/dock_workspace_values/dock_workspace_values.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// DockWorkspace's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/dock_workspace.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// How the program is asked before documents close at the user's request: one closing event per document (each, the default) or one for all (combined).
template <typename Declaring>
struct DockWorkspaceClosePromptCapability {
    PropertyCell<DockClosePrompt, DockWorkspaceClosePromptCapability<Declaring>> close_prompt{DockClosePrompt::each};

    static void assign(DockWorkspaceClosePromptCapability& capability, DockClosePrompt incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.close_prompt), incoming);
        if (!capability.close_prompt.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.close_prompt));
    }
};

// The workspace setting for opening an auto-hidden panel's flyout from its side tab; hover_or_click by default.
template <typename Declaring>
struct DockWorkspaceFlyoutOpeningCapability {
    PropertyCell<DockFlyoutOpening, DockWorkspaceFlyoutOpeningCapability<Declaring>> flyout_opening{DockFlyoutOpening::hover_or_click};

    static void assign(DockWorkspaceFlyoutOpeningCapability& capability, DockFlyoutOpening incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.flyout_opening), incoming);
        if (!capability.flyout_opening.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.flyout_opening));
    }
};

// Every DockWorkspace capability, in the order the declaring class takes them.
template <typename Declaring>
struct DockWorkspaceCapabilities : public DockWorkspaceClosePromptCapability<Declaring>,
                                   public DockWorkspaceFlyoutOpeningCapability<Declaring> {};

} // namespace gui_forms
